const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Macaya National Park geometry (Haiti)
  const macayaPark = ee.Geometry.Polygon([
    [[-74.05, 18.32], [-74.05, 18.42], [-73.95, 18.42], [-73.95, 18.32], [-74.05, 18.32]]
  ]);

  // 2. Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // Get relevant bands
  const treecover2000 = hansen.select('treecover2000');
  const lossYear = hansen.select('lossyear');

  // 3. Mask to areas with tree cover in 2000 (>10% threshold)
  const forestMask = treecover2000.gt(10);

  // 4. Calculate forest loss for period 2000-2015 (loss years 1-15)
  const loss2000_2015 = lossYear.gte(1).and(lossYear.lte(15)).and(forestMask);

  // 5. Calculate forest loss for period 2015-2022 (loss years 16-22)
  const loss2015_2022 = lossYear.gte(16).and(lossYear.lte(22)).and(forestMask);

  // 6. Count pixels with forest cover to check for C2
  const forestCount = forestMask.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: macayaPark,
    scale: 30,
    maxPixels: 1e9
  }).get('treecover2000');

  const forestPixels = await forestCount.getInfo();

  if (forestPixels === null || forestPixels === 0) {
    console.log('No forest pixels found in 2000.');
    console.log('<answer>C2</answer>');
    return;
  }

  console.log(`Forest pixels in 2000: ${Math.round(forestPixels)}`);

  // 7. Calculate loss area for both periods
  const loss1Stats = await loss2000_2015.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: macayaPark,
    scale: 30,
    maxPixels: 1e9
  }).get('lossyear').getInfo();

  const loss2Stats = await loss2015_2022.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: macayaPark,
    scale: 30,
    maxPixels: 1e9
  }).get('lossyear').getInfo();

  // 8. Validate results
  if (loss1Stats === null || loss2Stats === null) {
    console.log('Calculation failed to return valid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  const loss2000_2015_pixels = loss1Stats;
  const loss2015_2022_pixels = loss2Stats;

  // Convert pixels to hectares (30m resolution = 900 m²/pixel)
  const loss2000_2015_ha = (loss2000_2015_pixels * 900) / 10000;
  const loss2015_2022_ha = (loss2015_2022_pixels * 900) / 10000;

  console.log(`Forest loss 2000-2015: ${loss2000_2015_ha.toFixed(2)} ha (${loss2000_2015_pixels} pixels)`);
  console.log(`Forest loss 2015-2022: ${loss2015_2022_ha.toFixed(2)} ha (${loss2015_2022_pixels} pixels)`);

  // 9. Compare and provide answer
  if (loss2015_2022_pixels > loss2000_2015_pixels) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
